(() => {
"use strict";
const params=new URLSearchParams(location.search),siteSlug=params.get("site")||(window.GROCERY_STOREFRONT_CONFIG&&window.GROCERY_STOREFRONT_CONFIG.siteSlug)||"",preview=params.get("preview")==="1";
const root=document.getElementById("storefrontRoot"),toastNode=document.getElementById("sfToast");
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money=v=>"৳"+Number(v||0).toLocaleString("en-BD",{maximumFractionDigits:2});
const qs=v=>encodeURIComponent(String(v??""));
let state={website:null,pages:[],documents:[],categories:[],products:[],page:"home",cart:[],wishlist:[],lastOrder:null,filters:{category:"all",sort:"featured",search:""},mobileMenu:false,previewToken:null,previewOnly:false};
const templateInfo={
 "general-supermarket":{brand:"Daily Basket",eyebrow:"YOUR NEIGHBOURHOOD MARKET",heroImage:"https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1400&q=85",hero:"A better basket starts with better choices.",copy:"Everyday essentials, fresh favourites and pantry staples—thoughtfully selected for the people around your table.",badge:"WEEKLY MARKET PICKS",promise:["Fresh every day","Fair everyday value","Delivery that fits your day"],categoryIcons:["🥬","🥛","🍞","🍚","🥤","🧼"]},
 "fresh-produce":{brand:"Field & Fork",eyebrow:"GROWN WITH CARE · GATHERED WITH PURPOSE",heroImage:"https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=1400&q=85",hero:"Closer to the source. Fresher to your table.",copy:"Seasonal produce, grower stories and beautiful everyday staples—chosen with the land and your kitchen in mind.",badge:"IN SEASON NOW",promise:["Season-led selection","Know your growers","Good food, less fuss"],categoryIcons:["🥕","🍊","🌿","🍅","🥚","🍯"]},
 "express-grocery":{brand:"zipmart",eyebrow:"YOUR QUICK LOCAL STORE",heroImage:"https://images.unsplash.com/photo-1604719312566-8912e9c8a213?auto=format&fit=crop&w=1400&q=85",hero:"Need the good stuff? Get moving.",copy:"Your everyday essentials in a few quick taps. Build your bag, check out and get on with your day.",badge:"QUICK PICKS · QUICK DELIVERY",promise:["Fast add-to-bag","Simple checkout","Local delivery"],categoryIcons:["⚡","🥤","🍫","🥛","🧻","🍌"]},
 "wholesale-bulk":{brand:"Merchant Supply",eyebrow:"PROCUREMENT MADE PRACTICAL",heroImage:"https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1400&q=85",hero:"Dependable supply. Better buying decisions.",copy:"A business-first catalogue with clear pack sizes, minimum quantities and a streamlined repeat-order workflow.",badge:"BUSINESS BUYING PORTAL",promise:["Transparent pack sizes","Volume-ready ordering","One clear order sheet"],categoryIcons:["🌾","🛢️","📦","🥫","🧂","🚚"]}
};
const pageTitles={home:"Home",shop:"Shop All",category:"Category",product:"Product Details",search:"Search Results",cart:"Your Basket",checkout:"Checkout","order-confirmation":"Order Confirmation","order-tracking":"Track Order",about:"Our Story",contact:"Contact Us",faq:"FAQs",delivery:"Delivery Information",returns:"Returns & Refunds",privacy:"Privacy Policy",terms:"Terms & Conditions",account:"My Account",wishlist:"Wishlist",offers:"Special Offers",brands:"Brands",recipes:"Recipes & Ideas","recipe-detail":"Recipe Details",journal:"Journal","store-locator":"Find a Store","bulk-enquiry":"Bulk & Business Enquiry"};
function pageUrl(page,extra={}){const p=new URLSearchParams({site:siteSlug,page,...extra});if(preview)p.set("preview","1");const base=(window.GROCERY_STOREFRONT_CONFIG&&window.GROCERY_STOREFRONT_CONFIG.basePath)||"./";return base+"?"+p.toString();}
function imageUrl(p){return p?.image_url||p?.gallery?.[0]?.url||p?.gallery?.[0]||"";}
function getProduct(id){return state.products.find(p=>p.id===id);}
function getCategory(id){return state.categories.find(c=>c.id===id);}
function cartKey(){return "hf-storefront-cart-v2:"+siteSlug;}
function wishKey(){return "hf-storefront-wishlist-v1:"+siteSlug;}
function loadLocal(){try{state.cart=JSON.parse(localStorage.getItem(cartKey())||"[]");}catch(_){state.cart=[];}try{state.wishlist=JSON.parse(localStorage.getItem(wishKey())||"[]");}catch(_){state.wishlist=[];}}
function saveLocal(){try{localStorage.setItem(cartKey(),JSON.stringify(state.cart));localStorage.setItem(wishKey(),JSON.stringify(state.wishlist));}catch(_){notify("Your browser could not save this basket.");}}
function cartCount(){return state.cart.reduce((n,x)=>n+Number(x.quantity||0),0);}
function cartTotal(){return state.cart.reduce((n,x)=>{const p=getProduct(x.product_id);return n+(p?Number(p.price)*Number(x.quantity):0);},0);}
function notify(message){toastNode.textContent=message;toastNode.classList.add("is-visible");clearTimeout(notify.timer);notify.timer=setTimeout(()=>toastNode.classList.remove("is-visible"),2400);}
function docFor(page){return state.documents.find(d=>d.page_key===page)?.document||null;}
function pageCopy(page){const doc=docFor(page);return {title:doc?.page?.title||pageTitles[page]||"Page",heading:doc?.content?.heading||doc?.tree?.find(n=>n.type==="section")?.children?.find(n=>n.type==="heading")?.text||"",description:doc?.content?.description||doc?.tree?.find(n=>n.type==="section")?.children?.find(n=>n.type==="paragraph")?.text||""};}
function activeProducts(){return state.products.filter(p=>Number(p.stock)>0);}
function categoryName(p){return getCategory(p.category_id)?.name||"General";}
function card(p){const img=imageUrl(p),cat=categoryName(p),saved=state.wishlist.includes(p.id),stock=Number(p.stock)>0;return '<article class="sf-product-card"><a class="sf-product-media" href="'+pageUrl("product",{product:p.id})+'">'+(img?'<img loading="lazy" src="'+esc(img)+'" alt="'+esc(p.name)+'">':'')+'<span class="sf-product-tag">'+(p.compare_at_price&&Number(p.compare_at_price)>Number(p.price)?"SPECIAL":stock?"AVAILABLE":"SOLD OUT")+'</span></a><div class="sf-product-info"><small>'+esc(cat)+'</small><h3><a href="'+pageUrl("product",{product:p.id})+'">'+esc(p.name)+'</a></h3><div class="sf-product-bottom"><span class="sf-price">'+money(p.price)+'<small> / '+esc(p.unit||"piece")+'</small>'+(p.compare_at_price?'<del>'+money(p.compare_at_price)+'</del>':'')+'</span><button class="sf-add" data-add="'+esc(p.id)+'" '+(!stock?"disabled":"")+' aria-label="Add '+esc(p.name)+' to cart">'+(state.website.template_key==="wholesale-bulk"?"Add to order":"Add to cart")+'</button></div></div></article>';}
function productGrid(products){return products.length?'<div class="sf-product-grid">'+products.map(card).join("")+'</div>':'<div class="sf-empty"><h3>Your product shelf is waiting</h3><p>Add categories and products from the Halal Food admin catalogue to populate this storefront. Sample inventory is not used for real orders.</p><a class="sf-btn secondary" href="'+(preview?"./admin/products-add.html":"#")+'">Manage products</a></div>';}
function pageHead(kicker,title,desc,action=""){return '<header class="sf-page-head"><div><span class="sf-kicker">'+esc(kicker)+'</span><h1>'+esc(title)+'</h1><p>'+esc(desc)+'</p></div>'+action+'</header>';}
function hero(){const t=templateInfo[state.website.template_key]||templateInfo["general-supermarket"],copy=pageCopy("home");const heading=copy.heading&&copy.heading!=="A better way to shop, every day"?copy.heading:t.hero;const description=copy.description&&copy.description!=="Discover carefully selected favourites, fresh picks and everyday essentials."?copy.description:t.copy;const categories=state.categories.slice(0,6);return '<section class="sf-hero"><div class="sf-hero-copy"><span class="sf-kicker">'+esc(t.eyebrow)+'</span><h1>'+esc(heading)+'</h1><p>'+esc(description)+'</p><a class="sf-btn" href="'+pageUrl("shop")+'">Explore the store ↗</a><div class="sf-hero-trust">'+t.promise.map(x=>'<span>✓ '+esc(x)+'</span>').join("　")+'</div></div><div class="sf-hero-media">'+(state.website.brand?.hero_image||t.heroImage?'<img src="'+esc(state.website.brand?.hero_image||t.heroImage)+'" alt="">':'')+'<span class="sf-hero-badge">'+esc(t.badge)+'</span></div></section><section class="sf-section"><div class="sf-section-head"><div><span class="sf-kicker">BROWSE BY CATEGORY</span><h2>Find your kind of good</h2></div><a class="sf-btn secondary" href="'+pageUrl("shop")+'">View all</a></div><div class="sf-category-grid">'+(categories.length?categories.map((c,i)=>'<a class="sf-category-tile" href="'+pageUrl("category",{category:c.slug})+'"><span>'+t.categoryIcons[i%t.categoryIcons.length]+'</span><strong>'+esc(c.name)+' ↗</strong></a>').join(""):'<div class="sf-empty"><h3>Categories coming soon</h3><p>Create your store categories in the admin panel.</p></div>')+'</div></section><section class="sf-section"><div class="sf-section-head"><div><span class="sf-kicker">THE CURRENT EDIT</span><h2>Popular picks</h2><p>Products from your live catalogue</p></div><a class="sf-btn secondary" href="'+pageUrl("shop")+'">Shop all products</a></div>'+productGrid(activeProducts().slice(0,8))+'</section><section class="sf-section sf-content-panel"><span class="sf-kicker">A BETTER WAY TO BUY</span><h2>Good products. Clear choices. Thoughtful service.</h2><div class="sf-category-grid">'+t.promise.map((x,i)=>'<div class="sf-category-tile"><span>'+["✦","✓","↗"][i]+'</span><strong>'+esc(x)+'</strong></div>').join("")+'</div></section>';}
function filteredProducts(){let rows=activeProducts().slice();if(state.filters.category!=="all"){const cat=state.categories.find(c=>c.slug===state.filters.category);rows=rows.filter(p=>p.category_id===cat?.id);}if(state.filters.search){const q=state.filters.search.toLowerCase();rows=rows.filter(p=>(p.name+" "+p.description+" "+categoryName(p)).toLowerCase().includes(q));}if(state.filters.sort==="price-low")rows.sort((a,b)=>Number(a.price)-Number(b.price));if(state.filters.sort==="price-high")rows.sort((a,b)=>Number(b.price)-Number(a.price));if(state.filters.sort==="name")rows.sort((a,b)=>a.name.localeCompare(b.name));return rows;}
function shopPage(){const c=state.categories;return pageHead("THE FULL RANGE","Shop all products","Browse the complete catalogue, narrow by category and add your favourites in one place.")+'<div class="sf-toolbar"><div class="sf-filter-row"><button class="sf-chip '+(state.filters.category==="all"?"is-active":"")+'" data-filter-category="all">All</button>'+c.map(x=>'<button class="sf-chip '+(state.filters.category===x.slug?"is-active":"")+'" data-filter-category="'+esc(x.slug)+'">'+esc(x.name)+'</button>').join("")+'</div><select class="sf-sort" id="sfSort" aria-label="Sort products"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name</option></select></div><div id="sfProductResults">'+productGrid(filteredProducts())+'</div>';}
function categoryPage(){const slug=params.get("category")||"",cat=state.categories.find(c=>c.slug===slug);const rows=cat?state.products.filter(p=>p.category_id===cat.id):[];return pageHead("SHOP BY CATEGORY",cat?.name||"Category not found",cat?"Explore products in this collection.":"Choose a category from the shop page.",'<a class="sf-btn secondary" href="'+pageUrl("shop")+'">All products</a>')+productGrid(rows);}
function searchPage(){const q=params.get("q")||"";state.filters.search=q;return pageHead("SEARCH THE STORE","Search results",q?'Results for “'+q+'”':'Search the product catalogue.')+'<form class="sf-toolbar" id="sfSearchForm"><input class="sf-sort" style="flex:1;min-width:180px" name="q" value="'+esc(q)+'" placeholder="Search products, categories…" aria-label="Search products"><button class="sf-btn">Search</button></form>'+productGrid(filteredProducts());}
function productPage(){const p=getProduct(params.get("product"));if(!p)return '<div class="sf-empty"><h3>Product not found</h3><p>This product may be unavailable or removed from the catalogue.</p><a class="sf-btn" href="'+pageUrl("shop")+'">Back to shop</a></div>';const img=imageUrl(p),qtyMin=Math.max(1,Number(p.attributes?.minimum_order_quantity||1));return '<div class="sf-product-detail"><div class="sf-gallery-main">'+(img?'<img src="'+esc(img)+'" alt="'+esc(p.name)+'">':'')+'</div><div class="sf-product-copy"><span class="sf-kicker">'+esc(categoryName(p))+'</span><h1>'+esc(p.name)+'</h1><div class="sf-product-price">'+money(p.price)+' <small style="font-size:12px;color:var(--sf-muted)">/ '+esc(p.unit||"piece")+'</small></div><p>'+esc(p.description||"Carefully selected for your everyday needs.")+'</p><p><span class="sf-status-pill">'+(Number(p.stock)>0?"In stock":"Currently unavailable")+'</span>　<small>SKU: '+esc(p.sku||"—")+'</small></p>'+(p.attributes?.minimum_order_quantity?'<p>Minimum order: '+qtyMin+' '+esc(p.unit||"units")+'</p>':'')+'<div class="sf-product-actions"><label class="sf-qty"><button type="button" data-qty="-1">−</button><input id="sfProductQty" type="number" min="'+qtyMin+'" max="'+Math.max(qtyMin,Number(p.stock))+'" value="'+qtyMin+'"><button type="button" data-qty="1">+</button></label><button class="sf-btn" data-add="'+esc(p.id)+'" '+(Number(p.stock)<=0?"disabled":"")+'>'+ (state.website.template_key==="wholesale-bulk"?"Add to order":"Add to cart")+'</button><button class="sf-btn secondary" data-buy-now="'+esc(p.id)+'" '+(Number(p.stock)<=0?"disabled":"")+'>'+ (state.website.template_key==="wholesale-bulk"?"Request supply":"Buy now")+'</button></div><button class="sf-chip" data-wish="'+esc(p.id)+'">'+(state.wishlist.includes(p.id)?"♥ Saved to wishlist":"♡ Save to wishlist")+'</button><div class="sf-content-panel" style="margin-top:24px"><h3>Product information</h3><p>'+esc(p.description||"Product information will be updated by the store owner.")+'</p></div></div></div><section class="sf-section"><div class="sf-section-head"><h2>You may also like</h2></div>'+productGrid(state.products.filter(x=>x.id!==p.id&&x.category_id===p.category_id).slice(0,4))+'</section>';}
function cartRows(){return state.cart.map(item=>{const p=getProduct(item.product_id);if(!p)return "";return '<div class="sf-cart-row"><a href="'+pageUrl("product",{product:p.id})+'">'+(imageUrl(p)?'<img src="'+esc(imageUrl(p))+'" alt="">':'<div class="sf-product-media"></div>')+'</a><div><h3><a href="'+pageUrl("product",{product:p.id})+'">'+esc(p.name)+'</a></h3><small>'+money(p.price)+' / '+esc(p.unit||"piece")+'</small><div class="sf-cart-controls"><button data-cart-qty="-1" data-product="'+esc(p.id)+'">−</button><b>'+Number(item.quantity)+'</b><button data-cart-qty="1" data-product="'+esc(p.id)+'">+</button><button data-remove="'+esc(p.id)+'" aria-label="Remove product">Remove</button></div></div><strong>'+money(Number(p.price)*Number(item.quantity))+'</strong></div>';}).join("");}
function cartPage(){if(!cartCount())return '<div class="sf-empty"><h3>Your basket is taking a breather</h3><p>Find something good and add it to your basket.</p><a class="sf-btn" href="'+pageUrl("shop")+'">Start shopping</a></div>';return pageHead("YOUR SELECTION","Your basket","Review quantities and make sure everything is just right.")+'<div class="sf-cart-layout"><div class="sf-cart-list">'+cartRows()+'</div>'+summaryCard(true)+'</div>';}
function summaryCard(checkout=false){const delivery=Number(state.website.settings?.delivery?.default_fee||0);return '<aside class="sf-summary"><h3>Order summary</h3><div class="sf-summary-line"><span>Items ('+cartCount()+')</span><b>'+money(cartTotal())+'</b></div><div class="sf-summary-line"><span>Delivery estimate</span><b>'+money(delivery)+'</b></div><div class="sf-summary-total"><span>Total</span><strong>'+money(cartTotal()+delivery)+'</strong></div><small style="color:var(--sf-muted)">Final delivery charge is confirmed by the store at checkout.</small><div style="margin-top:18px">'+(checkout?'<button class="sf-btn" type="submit" form="sfCheckoutForm" style="width:100%">Place COD order →</button>':'<a class="sf-btn" style="width:100%" href="'+pageUrl("checkout")+'">Continue to checkout →</a>')+'</div><p><a href="'+pageUrl("shop")+'">← Continue shopping</a></p></aside>';}
function checkoutPage(){if(!cartCount())return cartPage();return pageHead("ALMOST THERE","Checkout","Complete your details. This store currently accepts cash on delivery only.")+'<div class="sf-checkout-layout"><form class="sf-form-card" id="sfCheckoutForm"><h3>Delivery details</h3><div class="sf-form-grid"><div class="sf-field"><label for="sfName">Full name *</label><input id="sfName" name="name" required maxlength="120" autocomplete="name"></div><div class="sf-field"><label for="sfPhone">Phone number *</label><input id="sfPhone" name="phone" required maxlength="24" autocomplete="tel" inputmode="tel"></div><div class="sf-field full"><label for="sfAddress">Full delivery address *</label><textarea id="sfAddress" name="address" required maxlength="600" autocomplete="street-address"></textarea></div><div class="sf-field"><label for="sfArea">Area / city</label><input id="sfArea" name="area" maxlength="120" autocomplete="address-level2"></div><div class="sf-field"><label for="sfPostcode">Postcode</label><input id="sfPostcode" name="postcode" maxlength="20" autocomplete="postal-code"></div><div class="sf-field full"><label for="sfNotes">Delivery notes</label><textarea id="sfNotes" name="notes" maxlength="1000" placeholder="Optional instructions"></textarea></div></div><div class="sf-content-panel"><strong>Payment method</strong><p>Cash on delivery (COD). Pay when your order arrives.</p></div><p><label><input type="checkbox" required> I confirm that my delivery information is correct.</label></p><button class="sf-btn" id="sfPlaceOrder" type="submit">Place COD order</button><p id="sfCheckoutError" role="alert" style="color:#b42318"></p></form>'+summaryCard(true)+'</div>';}
function orderConfirmation(){const order=state.lastOrder||(()=>{try{return JSON.parse(sessionStorage.getItem("hf-last-order:"+siteSlug)||"null");}catch(_){return null;}})();if(!order)return '<div class="sf-empty"><h3>No recent order in this browser</h3><p>Use Track Order to look up an existing order.</p><a class="sf-btn" href="'+pageUrl("order-tracking")+'">Track an order</a></div>';return '<div class="sf-content-panel" style="text-align:center;padding:clamp(28px,6vw,70px)"><span style="font-size:46px">✓</span><span class="sf-kicker">ORDER RECEIVED</span><h1 style="font-family:var(--sf-display);font-size:clamp(34px,5vw,54px)">Thank you. We have your order.</h1><p>Your order number is</p><h2 style="font-size:26px;color:var(--sf-primary)">'+esc(order.order_number)+'</h2><p>Total: <strong>'+money(order.total)+'</strong> · Cash on delivery</p><p>Keep this order number and your phone number to track progress.</p><a class="sf-btn" href="'+pageUrl("order-tracking",{order:order.order_number})+'">Track your order</a></div>';}
function trackingPage(){return pageHead("ORDER SUPPORT","Track your order","Enter the order number and the phone number used at checkout.")+'<div class="sf-content-panel"><form id="sfTrackForm" class="sf-form-grid"><div class="sf-field"><label for="sfOrderNumber">Order number</label><input id="sfOrderNumber" name="order" value="'+esc(params.get("order")||"")+'" required placeholder="HF-XXXXXXXXXX"></div><div class="sf-field"><label for="sfTrackPhone">Phone number</label><input id="sfTrackPhone" name="phone" required inputmode="tel"></div><div class="sf-field full"><button class="sf-btn">Track order</button></div></form><div id="sfTrackResult"></div></div>';}
function contentPage(key){
const copy=pageCopy(key),title=copy.title||pageTitles[key]||"Information",doc=docFor(key),content=doc?.content||{},blocks=Array.isArray(content.blocks)?content.blocks:[],faq=Array.isArray(content.faqs)?content.faqs:[];
const renderBlock=b=>'<section class="sf-rich-block"><h2>'+esc(b.heading||"")+'</h2>'+(Array.isArray(b.paragraphs)?b.paragraphs.map(p=>'<p>'+esc(p)+'</p>').join(""):"")+(Array.isArray(b.bullets)?'<ul>'+b.bullets.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>':"")+(Array.isArray(b.faqs)?b.faqs.map(x=>'<details class="sf-faq-item"><summary>'+esc(x.question)+'</summary><p>'+esc(x.answer)+'</p></details>').join(""):"")+'</section>';
let body=blocks.length?blocks.map(renderBlock).join(""):'<section class="sf-rich-block"><h2>'+esc(copy.heading||"More information")+'</h2><p>'+esc(copy.description||"Please contact the store for further information.")+'</p></section>';
if(faq.length)body+='<section class="sf-rich-block"><h2>Frequently asked questions</h2>'+faq.map(x=>'<details class="sf-faq-item"><summary>'+esc(x.question)+'</summary><p>'+esc(x.answer)+'</p></details>').join("")+'</section>';
const cta=key==="account"?'<a class="sf-btn" href="'+pageUrl("order-tracking")+'">Track an order</a>':key==="contact"?'<a class="sf-btn secondary" href="'+pageUrl("order-tracking")+'">Order support & tracking</a>':key==="bulk-enquiry"?'<a class="sf-btn" href="'+pageUrl("bulk-enquiry")+'">Open business enquiry</a>':"";
return pageHead("THE STORE",title,copy.description||"Helpful information from the store.")+'<div class="sf-content-panel sf-rich-content">'+body+(cta?'<div class="sf-rich-cta">'+cta+'</div>':"")+'</div>';
}
function offersPage(){const rows=activeProducts().filter(p=>Number(p.compare_at_price)>Number(p.price));return pageHead("THE GOOD VALUE EDIT","Special offers","Offers are calculated from the live product prices and compare-at prices in your catalogue.")+productGrid(rows);}
function brandsPage(){const brands=[...new Set(activeProducts().map(p=>String(p.attributes?.brand||"").trim()).filter(Boolean))];return pageHead("MEET THE MAKERS","Brands","Discover the makers and product ranges carried by this store.")+(brands.length?'<div class="sf-category-grid">'+brands.map(b=>'<a class="sf-category-tile" href="'+pageUrl("search",{q:b})+'"><span>✦</span><strong>'+esc(b)+' ↗</strong></a>').join("")+'</div>':'<div class="sf-empty"><h3>Brand directory is being curated</h3><p>Add brand names to product attributes in the admin catalogue to show them here.</p></div>')+productGrid(activeProducts().slice(0,4));}
function recipesPage(){const copy=pageCopy("recipes"),items=docFor("recipes")?.content?.recipes||[],descriptions=["A practical idea built around familiar pantry ingredients and a few fresh additions.","A simple combination for a balanced everyday meal. Adjust ingredients to your taste.","A flexible meal-prep idea for busy weekdays and shared tables.","A quick way to use seasonal ingredients before your next shop."];return pageHead("IDEAS FOR YOUR TABLE",copy.title||"Recipes & ideas",copy.description||"Inspiration for everyday cooking.")+'<div class="sf-content-panel"><h2>'+esc(copy.heading||"Cook something lovely")+'</h2><p>Explore approachable ideas, then browse the catalogue for ingredients and everyday favourites.</p></div><section class="sf-section"><div class="sf-section-head"><div><span class="sf-kicker">FROM OUR KITCHEN</span><h2>Ideas to try</h2></div></div><div class="sf-category-grid">'+(items.length?items.map((name,i)=>'<a class="sf-category-tile" href="'+pageUrl("recipe-detail",{recipe:qs(name)})+'"><span>'+["🥗","🍲","🥕","🍞"][i%4]+'</span><strong>'+esc(name)+' ↗</strong><small>'+esc(descriptions[i%descriptions.length])+'</small></a>').join(""):'<p>Recipe ideas are being prepared.</p>')+'</div></section><section class="sf-section"><div class="sf-section-head"><h2>Shop the ingredients</h2><a class="sf-btn secondary" href="'+pageUrl("shop")+'">View all</a></div>'+productGrid(activeProducts().slice(0,8))+'</section>';}
function recipeDetailPage(){const copy=pageCopy("recipe-detail");return pageHead("FROM THE RECIPE JOURNAL",copy.title||"Recipe details",copy.description||"A recipe story from the store.")+'<div class="sf-content-panel"><h2>'+esc(copy.heading||"Ingredients and method")+'</h2><p>Recipe ingredients, preparation steps and serving notes can be written and saved in the page editor. Related products from the live catalogue are shown below.</p></div><section class="sf-section">'+productGrid(activeProducts().slice(0,4))+'</section>';}
