function storeLocatorPage(){const delivery=state.website.settings?.delivery||{},areas=Array.isArray(delivery.areas)?delivery.areas:[];return pageHead("LOCAL SERVICE","Find a store or delivery area","Check the locations and areas configured by the store.")+'<div class="sf-content-panel"><h2>Where we serve</h2>'+(areas.length?'<ul>'+areas.map(x=>'<li>'+esc(typeof x==="string"?x:x.name||x.area||"Service area")+'</li>').join("")+'</ul>':'<p>Verified service zones have not been configured yet. The store owner must add real delivery areas and pickup addresses before this page can publish location details.</p>')+'<p>'+esc(delivery.note||"Delivery coverage is confirmed by the store at checkout.")+'</p><a class="sf-btn secondary" href="'+pageUrl("contact")+'">Ask about delivery</a></div>';}
function bulkEnquiryPage(){const email=state.website.brand?.email||"";return pageHead("BUSINESS CUSTOMERS","Bulk & business enquiry","Tell us what your business needs and contact the store team for a supply discussion.")+'<form class="sf-form-card" id="sfBulkEnquiry"><div class="sf-form-grid"><div class="sf-field"><label for="sfBulkName">Business / contact name</label><input id="sfBulkName" name="name" required></div><div class="sf-field"><label for="sfBulkPhone">Phone number</label><input id="sfBulkPhone" name="phone" required></div><div class="sf-field full"><label for="sfBulkNeed">Products and quantities required</label><textarea id="sfBulkNeed" name="message" required></textarea></div><div class="sf-field full"><button class="sf-btn" type="submit">Prepare enquiry</button><small id="sfBulkStatus" role="status"></small></div></div></form>'+(email?'<p class="sf-section">Or email <a class="sf-text-link" href="mailto:'+esc(email)+'">'+esc(email)+'</a></p>':'');}
