function renderFooter(){return '<footer class="sf-footer"><div class="sf-footer-inner"><div><h3>'+esc(state.website.brand?.name||templateInfo[state.website.template_key]?.brand||state.website.name)+'</h3><p>'+(esc(state.website.brand?.tagline||"Thoughtful products, clear choices and service you can count on."))+'</p></div><div><h4>Shop</h4><div class="sf-footer-links"><a href="'+pageUrl("shop")+'">All products</a><a href="'+pageUrl("cart")+'">Your basket</a><a href="'+pageUrl("wishlist")+'">Wishlist</a></div></div><div><h4>Help</h4><div class="sf-footer-links"><a href="'+pageUrl("contact")+'">Contact</a><a href="'+pageUrl("faq")+'">FAQs</a><a href="'+pageUrl("delivery")+'">Delivery</a><a href="'+pageUrl("returns")+'">Returns</a><a href="'+pageUrl("order-tracking")+'">Track order</a></div></div><div><h4>Information</h4><div class="sf-footer-links"><a href="'+pageUrl("about")+'">Our story</a><a href="'+pageUrl("offers")+'">Special offers</a><a href="'+pageUrl("brands")+'">Brands</a><a href="'+pageUrl("recipes")+'">Recipes</a><a href="'+pageUrl("journal")+'">Journal</a><a href="'+pageUrl("store-locator")+'">Find a store</a><a href="'+pageUrl("bulk-enquiry")+'">Business enquiry</a><a href="'+pageUrl("privacy")+'">Privacy</a><a href="'+pageUrl("terms")+'">Terms</a></div></div></div><div class="sf-footer-bottom">© '+new Date().getFullYear()+' '+esc(state.website.brand?.name||state.website.name)+'. All rights reserved.</div></footer>';}
function renderShell(){const brand=state.website.brand?.name||templateInfo[state.website.template_key]?.brand||state.website.name;const nav=[["home","Home"],["shop","Shop"],["offers","Offers"],["brands","Brands"],["recipes","Recipes"],["journal","Journal"],["about","Our story"],["store-locator","Find a store"],["delivery","Delivery"],["faq","FAQs"],["bulk-enquiry","Business"],["contact","Contact"],["order-tracking","Track order"]];return (preview?'<div class="sf-preview-bar"><strong>PRIVATE PREVIEW</strong> · This site is not public. Orders cannot be placed until it is published.</div>':'')+'<div class="sf-announcement">'+esc(state.website.brand?.announcement||"Thoughtful shopping · Reliable local service")+'</div><header class="sf-header"><div class="sf-header-inner"><a class="sf-brand" href="'+pageUrl("home")+'"><span class="sf-brand-mark">'+esc(brand.slice(0,2).toUpperCase())+'</span><span class="sf-brand-copy"><strong>'+esc(brand)+'</strong><small>'+esc(templateInfo[state.website.template_key]?.eyebrow||"ONLINE STORE")+'</small></span></a><form class="sf-search" id="sfHeaderSearch"><span>⌕</span><input name="q" placeholder="Search products and categories…" aria-label="Search products"></form><div class="sf-header-actions"><a class="sf-icon-btn" href="'+pageUrl("wishlist")+'">♡ Saved</a><a class="sf-cart-btn" href="'+pageUrl("cart")+'">Basket <span class="sf-cart-count">'+cartCount()+'</span></a><button class="sf-menu-btn" id="sfMenuToggle" aria-expanded="false" aria-label="Open menu">☰</button></div></div><nav class="sf-nav '+(state.mobileMenu?"is-open":"")+'" id="sfNav">'+nav.map(([key,label])=>'<a href="'+pageUrl(key)+'" '+(state.page===key?'aria-current="page"':'')+'>'+label+'</a>').join("")+'</nav></header>';}
function renderPage(){const key=state.page;switch(key){case"home":return hero();case"shop":return shopPage();case"category":return categoryPage();case"product":return productPage();case"search":return searchPage();case"cart":return cartPage();case"checkout":return checkoutPage();case"order-confirmation":return orderConfirmation();case"order-tracking":return trackingPage();case"wishlist":return wishlistPage();case"offers":return offersPage();case"brands":return brandsPage();case"recipes":return recipesPage();case"recipe-detail":return recipeDetailPage();case"journal":return journalPage();case"store-locator":return storeLocatorPage();case"bulk-enquiry":return bulkEnquiryPage();case"about":case"contact":case"faq":case"delivery":case"returns":case"privacy":case"terms":case"account":return contentPage(key);default:{const doc=docFor(key);if(doc)return contentPage(key);return '<div class="sf-empty"><h3>Page not found</h3><p>This page is not available in the current site.</p><a class="sf-btn" href="'+pageUrl("home")+'">Go home</a></div>';}}}
function render(){const brand=state.website.brand||{},template=state.website.template_key;document.body.dataset.template=template;document.title=(pageTitles[state.page]||"Store")+" · "+(brand.name||templateInfo[template]?.brand||state.website.name);const main=renderPage();root.innerHTML=(state.previewOnly?'<div role="status" style="padding:11px 18px;text-align:center;background:#fff4d8;color:#714b12;font:600 13px/1.5 Arial,sans-serif;border-bottom:1px solid #ead39a">TEMPLATE PREVIEW · Connect and publish this store from the WordPress admin to enable its live catalogue and checkout.</div>':'')+renderShell()+'<main class="sf-main">'+main+'</main>'+renderFooter()+(template==="express-grocery"&&cartCount()?'<div class="sf-mobile-cart"><div><span>YOUR BAG</span><br><strong>'+cartCount()+' items · '+money(cartTotal())+'</strong></div><a class="sf-btn" href="'+pageUrl("cart")+'">View basket →</a></div>':'');bind();}
function bind(){root.querySelector("#sfMenuToggle")?.addEventListener("click",()=>{state.mobileMenu=!state.mobileMenu;root.querySelector("#sfNav")?.classList.toggle("is-open",state.mobileMenu);root.querySelector("#sfMenuToggle")?.setAttribute("aria-expanded",String(state.mobileMenu));});root.querySelector("#sfHeaderSearch")?.addEventListener("submit",e=>{e.preventDefault();const q=new FormData(e.currentTarget).get("q")||"";location.href=pageUrl("search",{q});});root.querySelector("#sfSearchForm")?.addEventListener("submit",e=>{e.preventDefault();const q=new FormData(e.currentTarget).get("q")||"";location.href=pageUrl("search",{q});});root.querySelector("#sfSort")?.addEventListener("change",e=>{state.filters.sort=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});root.querySelector("#sfCheckoutForm")?.addEventListener("submit",submitOrder);root.querySelector("#sfTrackForm")?.addEventListener("submit",trackOrder);root.querySelector("#sfBulkEnquiry")?.addEventListener("submit",e=>{e.preventDefault();const email=state.website.brand?.email||"";const data=new FormData(e.currentTarget);const body="Business: "+data.get("name")+"\nPhone: "+data.get("phone")+"\nRequirements: "+data.get("message");if(email){location.href="mailto:"+email+"?subject="+encodeURIComponent("Bulk supply enquiry")+"&body="+encodeURIComponent(body);}else{root.querySelector("#sfBulkStatus").textContent="Please contact the store using its published contact details to complete this enquiry.";}});bindDynamic();}
function bindDynamic(){root.querySelectorAll("[data-add]").forEach(b=>b.addEventListener("click",()=>addToCart(b.dataset.add)));root.querySelectorAll("[data-buy-now]").forEach(b=>b.addEventListener("click",()=>{addToCart(b.dataset.buyNow,Number(root.querySelector("#sfProductQty")?.value)||1,true);}));root.querySelectorAll("[data-wish]").forEach(b=>b.addEventListener("click",()=>toggleWish(b.dataset.wish)));root.querySelectorAll("[data-filter-category]").forEach(b=>b.addEventListener("click",()=>{state.filters.category=b.dataset.filterCategory;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());root.querySelectorAll("[data-filter-category]").forEach(x=>x.classList.toggle("is-active",x===b));bindDynamic();}));root.querySelectorAll("[data-cart-qty]").forEach(b=>b.addEventListener("click",()=>changeCart(b.dataset.product,Number(b.dataset.cartQty))));root.querySelectorAll("[data-remove]").forEach(b=>b.addEventListener("click",()=>{state.cart=state.cart.filter(x=>x.product_id!==b.dataset.remove);saveLocal();render();}));root.querySelectorAll("[data-qty]").forEach(b=>b.addEventListener("click",()=>{const input=root.querySelector("#sfProductQty");if(input)input.value=Math.max(Number(input.min)||1,Math.min(Number(input.max)||999,Number(input.value||1)+Number(b.dataset.qty)));}));}
function addToCart(id,quantity=1,buyNow=false){const p=getProduct(id);if(!p||Number(p.stock)<=0){notify("This product is currently unavailable.");return;}const qty=Math.max(Number(p.attributes?.minimum_order_quantity||1),Number(quantity)||1);const row=state.cart.find(x=>x.product_id===id);const next=(row?.quantity||0)+qty;if(next>Number(p.stock)){notify("The requested quantity is not available in stock.");return;}if(row)row.quantity=next;else state.cart.push({product_id:id,quantity:qty});saveLocal();notify("Added to your basket.");if(buyNow)location.href=pageUrl("checkout");else render();}
function changeCart(id,delta){const row=state.cart.find(x=>x.product_id===id),p=getProduct(id);if(!row)return;row.quantity=Math.max(0,Math.min(Number(p?.stock||0),Number(row.quantity)+delta));state.cart=state.cart.filter(x=>x.quantity>0);saveLocal();render();}
function toggleWish(id){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];saveLocal();notify(state.wishlist.includes(id)?"Saved to wishlist.":"Removed from wishlist.");render();}
async function submitOrder(e){e.preventDefault();const error=root.querySelector("#sfCheckoutError"),btn=root.querySelector("#sfPlaceOrder");if(preview){error.textContent="Orders are disabled in private preview. Publish the website before accepting customer orders.";return;}if(!cartCount()){error.textContent="Your basket is empty.";return;}const form=new FormData(e.currentTarget);const customer={name:String(form.get("name")||"").trim(),phone:String(form.get("phone")||"").trim()};const shipping={name:customer.name,phone:customer.phone,address:String(form.get("address")||"").trim(),area:String(form.get("area")||"").trim(),postcode:String(form.get("postcode")||"").trim()};const items=state.cart.map(x=>({product_id:x.product_id,quantity:x.quantity}));btn.disabled=true;btn.textContent="Submitting order…";error.textContent="";try{const result=await window.HFNeonBuilderApi.placeOrder(siteSlug,items,customer,shipping,String(form.get("notes")||""));state.lastOrder=result;try{sessionStorage.setItem("hf-last-order:"+siteSlug,JSON.stringify(result));}catch(_){}state.cart=[];saveLocal();location.href=pageUrl("order-confirmation",{order:result.order_number});}catch(err){error.textContent=err.message||"Order could not be submitted. Please check your details and try again.";btn.disabled=false;btn.textContent="Place COD order";}}
async function trackOrder(e){e.preventDefault();const form=new FormData(e.currentTarget),box=root.querySelector("#sfTrackResult");box.textContent="Checking order…";try{const result=await window.HFNeonBuilderApi.trackOrder(siteSlug,String(form.get("order")||""),String(form.get("phone")||""));if(!result){box.innerHTML='<p role="alert">No order matched those details. Check the order number and phone number.</p>';return;}const statuses=["pending","processing","shipped","delivered"];const current=statuses.indexOf(result.status);box.innerHTML='<div class="sf-content-panel"><span class="sf-kicker">ORDER '+esc(result.order_number)+'</span><h2>Current status: '+esc(result.status)+'</h2><p>Total '+money(result.total)+' · Payment '+esc(result.payment_status)+'</p><div class="sf-timeline">'+statuses.map((s,i)=>'<span class="'+(i<=current?"is-done":"")+'">'+s+'</span>').join("")+'</div><ul>'+result.items.map(x=>'<li>'+esc(x.product?.name||"Product")+' × '+esc(x.quantity)+' — '+money(x.line_total)+'</li>').join("")+'</ul></div>';}catch(err){box.textContent=err.message||"Order lookup failed.";}}
async function getPreviewToken(){if(!preview)return null;const client=await window.HFNeonClientReady;if(!client)throw new Error("Independent Neon authentication is unavailable.");const {data,error}=await client.auth.getSession();if(error||!data?.session?.user?.id)throw new Error("Sign in to the independent WordPress workspace to preview this draft.");return null;}
async function boot(){if(!siteSlug){throw new Error("A storefront site address is required.");}state.previewToken=await getPreviewToken();const data=await window.HFNeonBuilderApi.loadStorefrontData(siteSlug,{token:state.previewToken,preview});state.website=data.website;state.pages=data.pages;state.documents=data.documents;state.categories=data.categories;state.products=data.products;state.previewOnly=!!data.previewOnly;state.page=params.get("page")||"home";if(!state.pages.some(p=>p.page_key===state.page)&&!state.documents.some(d=>d.page_key===state.page))state.page="home";loadLocal();render();}
boot().catch(err=>{console.error("Storefront load failed",err);root.innerHTML='<main class="sf-main"><div class="sf-empty"><h3>Storefront could not be opened</h3><p>'+esc(err.message||"Please try again later.")+'</p>'+(preview?'<a class="sf-btn" href="./admin/website-pages.html">Back to Website Pages</a>':'')+'</div></main>';});
})();

